const items = $input.all();
const results = [];

for (const item of items) {
  const { agentType, action } = item.json;

  // Call ABOS API to execute agent task
  try {
    const response = await $http.post('http://host.docker.internal:3001/api/agents/execute', {
      agentType,
      action,
      payload: {}
    });

    results.push({
      json: {
        agentType,
        success: true,
        result: response.data
      }
    });
  } catch (error) {
    results.push({
      json: {
        agentType,
        success: false,
        error: error.message
      }
    });
  }
}

return results;

const items = $input.all();
const agentResults = items.map(item => item.json);

const successful = agentResults.filter(r => r.success).length;
const failed = agentResults.filter(r => !r.success).length;

// Generate CEO report
const report = {
  date: new Date().toISOString().split('T')[0],
  summary: `Daily report: ${successful} agents completed, ${failed} failed`,
  agentStatuses: agentResults.map(r => ({
    agent: r.agentType,
    status: r.success ? 'completed' : 'failed',
    error: r.error
  })),
  completedTasks: successful,
  pendingTasks: failed,
  alerts: agentResults.filter(r => !r.success).map(r => `${r.agentType}: ${r.error}`),
  recommendations: []
};

if (failed > 0) {
  report.recommendations.push('Investigate failed agent executions');
}
if (successful === agentResults.length) {
  report.recommendations.push('All agents healthy - continue operations');
}

return [{ json: report }];
